target.css:
:root {
  --paper: #fffdf7;
  --ink: #243342;
  --muted: #6d7985;
  --line: #dbe2e5;
  --navy: #294a66;
  --blue-pale: #e8f1f7;
  --gold: #d89d35;
  --gold-pale: #fff3d8;
  --green: #367557;
  --green-pale: #e8f5ec;
}

.pairing-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--navy);
  border-radius: 14px;
}

.pairing-card * {
  box-sizing: border-box;
}

.card-header,
.matchup,
.card-footer,
.player,
.details li {
  display: flex;
  align-items: center;
}

.card-header {
  justify-content: space-between;
  margin-bottom: 13px;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pairing-card h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
}

.round-badge {
  padding: 5px 9px;
  color: var(--navy);
  background: var(--blue-pale);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.matchup {
  justify-content: space-between;
  gap: 10px;
  padding: 12px;
  background: var(--blue-pale);
  border-radius: 10px;
}

.player {
  gap: 8px;
  min-width: 0;
  flex: 1;
}

.black-player {
  justify-content: flex-end;
  text-align: right;
}

.piece {
  display: grid;
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  place-items: center;
  color: var(--gold);
  background: var(--gold-pale);
  border-radius: 9px;
  font-size: 23px;
}

.black-player .piece {
  color: var(--paper);
  background: var(--navy);
}

.player strong,
.player small {
  display: block;
  white-space: nowrap;
}

.player strong {
  font-size: 14px;
}

.player small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 11px;
}

.versus {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 0;
  margin: 12px 0;
  list-style: none;
}

.details li {
  justify-content: space-between;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 11px;
}

.details span {
  color: var(--muted);
}

.details strong {
  font-size: 11px;
}

.card-footer {
  gap: 6px;
  color: var(--green);
  font-size: 12px;
  font-weight: 600;
}

.ready-dot {
  width: 8px;
  height: 8px;
  background: var(--green);
  border-radius: 50%;
}

.card-footer button {
  margin-left: auto;
  padding: 0;
  color: var(--navy);
  background: transparent;
  border: 0;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

